import csv,re
REV=[r'\breview\b',r'\bsurvey\b',r'\boverview\b',r'\bperspective\b',r'position paper',r'\bopinion\b',r'\beditorial\b',r'commentary',r'viewpoint',r'bibliometric',r'\bscoping\b',r'systematic (literature )?review',r'narrative',r'\btaxonomy\b',r'\broadmap\b',r'\bvision\b',r'this chapter',r'we (discuss|argue|highlight|outline|explore|examine|review|summari[sz]e|synthesi[sz]e)',r'this (paper|article|work|study) (discusses|explores|examines|reviews|highlights|outlines|surveys|provides an overview|presents an overview|aims to (explore|review|discuss|provide an overview))',r'state[- ]of[- ]the[- ]art',r'challenges',r'opportunities',r'potential',r'future (directions|perspectives|research)',r'concept(ual)?\b',r'ethic',r'literature']
PRI=[r'we (propose|present|develop|implement|evaluate|built|designed|validated|trained|conducted|collected|tested|demonstrate)',r'results (show|showed|demonstrate|indicate|reveal|confirm)',r'\bexperiment',r'\bdataset',r'\baccuracy\b',r'\bauc\b',r'\bpatients (were|with)\b',r'\bparticipants\b',r'case study',r'\bprototype',r'\bimplemented\b',r'outperform',r'\bvalidat(ed|ion)\b',r'\bcohort\b',r'\bn ?= ?\d+',r'\b\d+ (patients|participants|subjects)\b',r'\bcalibrat',r'\bmodel(l)?ing\b.*\bpredict']
def score(t): return sum(bool(re.search(p,t)) for p in REV)-sum(bool(re.search(p,t)) for p in PRI)
